<script setup lang="ts">import{shallowRef,watch}from'vue';import{accountsApi,type PermissionView}from'@/api/accounts';import type{AccountSummary}from'@/types/security';const props=defineProps<{modelValue:boolean;account:AccountSummary|null}>();const emit=defineEmits<{(e:'update:modelValue',v:boolean):void}>();const rows=shallowRef<PermissionView[]>([]),busy=shallowRef(false);watch(()=>[props.modelValue,props.account?.id],async()=>{if(props.modelValue&&props.account)rows.value=await accountsApi.permissions(props.account.id)});async function change(row:PermissionView,value:PermissionView['permission']){if(!props.account)return;busy.value=true;try{await accountsApi.setPermission(props.account.id,row.repositoryId,value);rows.value=await accountsApi.permissions(props.account.id)}finally{busy.value=false}}</script>
<template><el-dialog :model-value="modelValue" :title="`仓库权限 · ${account?.displayName??''}`" width="620" @update:model-value="emit('update:modelValue',$event)"><el-alert title="READ 可查看；MAINTAIN 可同步和建索引；MANAGE 可删除仓库及派生数据。" type="info" :closable="false"/><el-table :data="rows" v-loading="busy" style="margin-top:16px"><el-table-column prop="repositoryName" label="仓库"/><el-table-column label="权限" width="220"><template #default="{row}"><el-select :model-value="row.permission" clearable placeholder="无权限" @change="change(row,$event)"><el-option label="只读" value="READ"/><el-option label="维护" value="MAINTAIN"/><el-option label="管理" value="MANAGE"/></el-select></template></el-table-column></el-table></el-dialog></template>
